from collections import deque

def find_connected_component(grid, start_r, start_c, color):
    """Find all cells in the same connected component as (start_r, start_c)"""
    hi, wi = len(grid), len(grid[0])
    visited = set()
    component = []
    q = deque([(start_r, start_c)])
    visited.add((start_r, start_c))

    while q:
        r, c = q.popleft()
        component.append((r, c))
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < hi and 0 <= nc < wi:
                if grid[nr][nc] == color and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
    return component

def bounding_box(component):
    """Return (min_r, max_r, min_c, max_c) for a set of (r,c)"""
    if not component:
        return (0, 0, 0, 0)
    return (min(c[0] for c in component), max(c[0] for c in component),
            min(c[1] for c in component), max(c[1] for c in component))

def normalize_component(component):
    """Affine transform component to (0,0) -> 0,0 (relative coordinates)"""
    min_r = min(c[0] for c in component)
    min_c = min(c[1] for c in component)
    return [(r - min_r, c - min_c) for r, c in component]

