def component_centroid(component):
    """Compute centroid (average) of component"""
    if not component:
        return (0, 0)
    avg_r = sum(c[0] for c in component) / len(component)
    avg_c = sum(c[1] for c in component) / len(component)
    return (avg_r, avg_c)

